"""Filesystem predicates shared by the bfs command evaluator."""
import fnmatch
import grp
import os
import pwd
import re
import stat
import time


def number_match(value, spec):
    """find-style integer comparison: N exact, +N greater, -N less."""
    spec = str(spec)
    cmp = spec[:1] if spec[:1] in "+-" else ""
    n = int(spec[1:] if cmp else spec)
    return value > n if cmp == "+" else value < n if cmp == "-" else value == n


def _mode(path, follow):
    if not follow:
        return os.lstat(path)
    try:
        return os.stat(path, follow_symlinks=True)
    except OSError:
        # find still sees a dangling link under -L; it simply cannot follow it.
        return os.lstat(path)


def _type_match(st, types):
    m = st.st_mode
    table = {
        "b": stat.S_ISBLK(m), "c": stat.S_ISCHR(m), "d": stat.S_ISDIR(m),
        "p": stat.S_ISFIFO(m), "f": stat.S_ISREG(m), "l": stat.S_ISLNK(m),
        "s": stat.S_ISSOCK(m), "D": False,
    }
    return any(table.get(t, False) for t in types.replace(",", ""))


def _permission_match(mode, spec):
    # find's -perm octal modes; '-' means all requested bits, '/' means any.
    prefix = spec[:1] if spec[:1] in "-/" else ""
    value = spec[1:] if prefix else spec
    try:
        wanted = int(value, 8)
    except ValueError:
        return False
    actual = stat.S_IMODE(mode)
    if prefix == "-":
        return actual & wanted == wanted
    if prefix == "/":
        return wanted == 0 or bool(actual & wanted)
    return actual == wanted


def evaluate(path, test, arg=None, depth=None, follow=False):
    """Evaluate a common bfs test. Unknown/unavailable tests return False."""
    try:
        st = _mode(path, follow)
    except OSError:
        return False
    t = test.lstrip("-")
    if t == "true": return True
    if t == "false": return False
    if t in ("type", "xtype"):
        if t == "xtype" and stat.S_ISLNK(os.lstat(path).st_mode):
            try: st = os.stat(path)
            except OSError: return "l" in str(arg).replace(",", "")
        return _type_match(st, str(arg))
    if t == "empty":
        if stat.S_ISDIR(st.st_mode):
            try: return next(os.scandir(path), None) is None
            except OSError: return False
        return stat.S_ISREG(st.st_mode) and st.st_size == 0
    if t == "size":
        spec = str(arg); unit = spec[-1:] if spec[-1:] in "cwbkMGTP" else "b"
        number = spec[:-1] if spec[-1:] in "cwbkMGTP" else spec
        divisor = {"c": 1, "w": 2, "b": 512, "k": 1024, "M": 1024**2,
                   "G": 1024**3, "T": 1024**4, "P": 1024**5}[unit]
        # size rounds up to unit, including default 512-byte blocks
        return number_match((st.st_size + divisor - 1) // divisor, number)
    if t == "perm": return _permission_match(st.st_mode, str(arg))
    if t in ("uid", "gid", "inum", "links"):
        return number_match({"uid": st.st_uid, "gid": st.st_gid, "inum": st.st_ino,
                             "links": st.st_nlink}[t], arg)
    if t in ("user", "group"):
        try:
            wanted = pwd.getpwnam(str(arg)).pw_uid if t == "user" else grp.getgrnam(str(arg)).gr_gid
        except KeyError:
            return False
        return (st.st_uid if t == "user" else st.st_gid) == wanted
    if t == "hidden": return os.path.basename(os.fspath(path).rstrip(os.sep)).startswith(".") and os.path.basename(os.fspath(path).rstrip(os.sep)) not in (".", "..")
    if t in ("readable", "writable", "executable"):
        return os.access(path, {"readable": os.R_OK, "writable": os.W_OK, "executable": os.X_OK}[t], follow_symlinks=follow)
    if t in ("name", "iname"):
        name = os.path.basename(os.fspath(path).rstrip(os.sep)) or os.sep
        return fnmatch.fnmatchcase(name.lower(), str(arg).lower()) if t == "iname" else fnmatch.fnmatchcase(name, str(arg))
    if t in ("lname", "ilname"):
        if not stat.S_ISLNK(os.lstat(path).st_mode): return False
        target = os.readlink(path)
        return fnmatch.fnmatchcase(target.lower(), str(arg).lower()) if t == "ilname" else fnmatch.fnmatchcase(target, str(arg))
    if t in ("path", "wholename", "ipath", "iwholename"):
        value = os.fspath(path)
        return fnmatch.fnmatchcase(value.lower(), str(arg).lower()) if t.startswith("i") else fnmatch.fnmatchcase(value, str(arg))
    if t == "depth": return depth is not None and number_match(depth, arg)
    if t == "samefile":
        try: return os.path.samefile(path, str(arg))
        except OSError: return False
    if t == "newer":
        try: return st.st_mtime > os.stat(str(arg)).st_mtime
        except OSError: return False
    if t == "sparse":
        blocks = getattr(st, "st_blocks", (st.st_size + 511) // 512)
        return blocks * 512 < st.st_size
    if t == "links": return number_match(st.st_nlink, arg)
    if t in ("mtime", "atime", "ctime", "mmin", "amin", "cmin"):
        attr = {"mtime":"st_mtime", "atime":"st_atime", "ctime":"st_ctime",
                "mmin":"st_mtime", "amin":"st_atime", "cmin":"st_ctime"}[t]
        age = max(0, time.time() - getattr(st, attr))
        scale = 60 if t.endswith("min") else 86400
        return number_match(int(age // scale), arg)
    return False

